        if w in canon: fl.append(canon[w]); i+=1
        elif w in options: fl.append(options[w]); i+=2
        elif re.fullmatch(r'-[a-zA-Z]+', w) and all('-'+c in canon for c in w[1:]): fl += [canon['-'+c] for c in w[1:]]; i+=1
