 "uniq --all-repeated=separate in.txt", "uniq --group in.txt out.txt", "uniq --group=separate in.txt", "uniq --group=both in.txt",
 "uniq -u in.txt", "uniq -d in.txt", "uniq -z in.txt", "uniq -i -f 1 -s 1 -w 3 in.txt out.txt", "uniq in.txt out.txt extra",
]
for c in cases:
