    r = subprocess.run(["uniq"]+words, input="a\na\nb\n", capture_output=True, text=True, cwd="/tmp/uniqtest")
    io = IO(fl, ops)
    try: io.generate_info(); iores = io.log
    except Exception as e: iores = f"EXC: {e}"
    pa = PA(fl, ops); pa.generate_info()
